/* prog20_anagram_checker – reconstructed from the obfuscated binary
 *
 * Behaviour (exactly as the original program):
 *
 * 1. If the program is invoked with fewer than 3 arguments
 *    (i.e. missing either the first or the second string),
 *    it prints the single line:
 *        USAGE
 *
 * 2. If either of the two supplied strings is longer than 1024
 *    characters (i.e. length >= 1025), it prints:
 *        TOO_LONG
 *
 * 3. Otherwise the program checks whether the two strings are anagrams.
 *    * All space characters (' ') are ignored.
 *    * Upper‑case letters are converted to lower‑case before counting.
 *    * Every other character (digits, punctuation, etc.) is counted
 *      unchanged.
 *    * The two strings are anagrams iff the frequency table of the
 *      processed characters is identical for both strings.
 *
 *    If they are anagrams it prints:
 *        ANAGRAM
 *    else it prints:
 *        NOT_ANAGRAM
 *
 * The output is produced with a single call to `puts()`, exactly like the
 * original binary.
 */

#include <stdio.h>
#include <string.h>

#define MAX_LEN 1024          /* 0x400 bytes, the limit used by the binary */

int main(int argc, char *argv[])
{
    /* 1. Argument count check – the original only checks for “too few”. */
    if (argc < 3) {
        puts("USAGE");
        return 0;
    }

    const char *s1 = argv[1];
    const char *s2 = argv[2];

    /* 2. Length check – both strings must be shorter than 1025 bytes. */
    if (strlen(s1) >= MAX_LEN + 1 || strlen(s2) >= MAX_LEN + 1) {
        puts("TOO_LONG");
        return 0;
    }

    /* 3. Build frequency tables (256 entries, one per possible byte). */
    int cnt1[256] = {0};
    int cnt2[256] = {0};

    /* Count characters of the first string */
    for (size_t i = 0; s1[i] != '\0'; ++i) {
        unsigned char c = (unsigned char)s1[i];
        if (c == ' ')               /* spaces are ignored */
            continue;
        if (c >= 'A' && c <= 'Z')   /* case‑insensitive for letters */
            c = c + ('a' - 'A');    /* convert to lower case */
        cnt1[c]++;                  /* all other bytes are counted as‑is */
    }

    /* Count characters of the second string */
    for (size_t i = 0; s2[i] != '\0'; ++i) {
        unsigned char c = (unsigned char)s2[i];
        if (c == ' ')
            continue;
        if (c >= 'A' && c <= 'Z')
            c = c + ('a' - 'A');
        cnt2[c]++;
    }

    /* 4. Compare the two tables */
    if (memcmp(cnt1, cnt2, sizeof(cnt1)) == 0)
        puts("ANAGRAM");
    else
        puts("NOT_ANAGRAM");

    return 0;
}
